// EP12 - read the site photo + the note that came with it.
// Nothing here is client data: every value comes from the POSTed body or the constants below.
const TRADE_CODE = "roofing"; // which slice of the rate card this lane quotes for
const CURRENCY = "GBP"; // rate-card currency - must match your Data Table
const TAX_RATE = 0.2; // 20% VAT. Set to 0 if you quote tax-exclusive.
const MAX_NOTE_LEN = 1200; // the vision call only ever sees this much of the note

// Field names are chosen defensively. n8n's expression sandbox refuses some identifiers
// outright (EP11: `{{ $json.caller }}` -> "Cannot access \"caller\" due to security concerns"),
// so nothing downstream is named caller / callee / arguments / constructor / prototype.
function firstOf(src, keys) {
  for (const k of keys) {
    const v = src[k];
    if (v !== undefined && v !== null && String(v).trim() !== "")
      return String(v).trim();
  }
  return "";
}

const stamp = new Date().toISOString();

return items.map((entry, idx) => {
  const src = entry.json.body ?? entry.json;

  const photoUrl = firstOf(src, [
    "photo_url",
    "photoUrl",
    "image_url",
    "imageUrl",
    "file_url",
    "attachment_url",
  ]);
  const note = firstOf(src, [
    "note",
    "site_note",
    "message",
    "body_text",
    "description",
    "comments",
  ]).slice(0, MAX_NOTE_LEN);
  const who =
    firstOf(src, ["from_name", "sender_name", "requester_name", "name"]) ||
    "site (unnamed)";
  const mail = firstOf(src, [
    "from_email",
    "sender_email",
    "requester_email",
    "email",
  ]);
  const address =
    firstOf(src, ["site_ref", "job_ref", "address_ref", "reference"]) ||
    "no-site-ref";

  // A quote reference we control. Never the customer's name, never their address.
  const ref =
    "Q-" +
    stamp.slice(0, 10).replace(/-/g, "") +
    "-" +
    String(idx + 1).padStart(3, "0");

  const httpsPhoto = /^https:\/\/\S+$/i.test(photoUrl);
  const intake = !httpsPhoto
    ? "rejected_no_usable_photo"
    : note === ""
      ? "accepted_photo_only"
      : "accepted_photo_and_note";

  return {
    json: {
      quote_ref: ref,
      received_at: stamp,
      photo_url: httpsPhoto ? photoUrl : "",
      site_note: note,
      site_ref: address,
      requester_name: who,
      requester_email: mail,
      trade_code: TRADE_CODE,
      currency_code: CURRENCY,
      tax_rate: TAX_RATE,
      intake_status: intake,
    },
  };
});

// EP12 - turn the rate card rows + the intake item into ONE vision request body.
// Runs once for all items: input here is every row of ep12_rate_card.
const MODEL = "anthropic/claude-sonnet-4.5"; // any vision model your endpoint serves
const MAX_TOKENS = 1500;
const MAX_LINES = 12; // refuse to draft a novel

const intake = $("Read the photo and the note").first().json;

// The rate card is the ONLY source of prices. The model never sees a price it can change,
// and never invents one: it may only return item_code + qty. Pricing happens in the next node.
const card = items
  .map((r) => r.json)
  .filter(
    (r) =>
      !r.trade_code ||
      !intake.trade_code ||
      String(r.trade_code) === String(intake.trade_code) ||
      String(r.trade_code) === "any",
  )
  .map((r) => ({
    item_code: String(r.item_code ?? ""),
    item_label: String(r.item_label ?? ""),
    unit_label: String(r.unit_label ?? ""),
  }))
  .filter((r) => r.item_code !== "");

const catalogue = card
  .map((r) => `${r.item_code} | ${r.item_label} | priced ${r.unit_label}`)
  .join("\n");

const systemText = [
  "You are a quantity surveyor reading one photograph from a building site.",
  "You may ONLY select work items from the catalogue given to you, by their exact item_code.",
  "You never invent an item_code. You never state, guess or adjust a price - you are not shown prices.",
  "If the photo is too dark, too tight, or too ambiguous to judge, say so and return fewer items.",
  "Quantities are estimates from a photo, not measurements. Be conservative: under-quote rather than over-quote.",
  `Return at most ${MAX_LINES} line items.`,
  "Reply with JSON only, no prose, in exactly this shape:",
  '{"observed":"one sentence on what is visibly wrong","lines":[{"item_code":"X","qty":1,"reason":"why this photo justifies it"}],"confidence":0.0,"needs_site_visit":false,"missing_info":["what a human must confirm"]}',
].join(" ");

const userText = [
  "CATALOGUE (item_code | description | unit):",
  catalogue || "(empty - the rate card returned no rows for this trade)",
  "",
  "NOTE FROM SITE:",
  intake.site_note || "(no note was sent with the photo)",
  "",
  "Read the photograph and return the JSON.",
].join("\n");

const requestBody = {
  model: MODEL,
  max_tokens: MAX_TOKENS,
  temperature: 0,
  messages: [
    { role: "system", content: systemText },
    {
      role: "user",
      content: [
        { type: "text", text: userText },
        { type: "image_url", image_url: { url: intake.photo_url } },
      ],
    },
  ],
};

return [
  {
    json: {
      quote_ref: intake.quote_ref,
      intake_status: intake.intake_status,
      card_rows: card.length,
      request_body: requestBody,
    },
  },
];

// EP12 - price the model's picks against the rate card. THE MODEL'S NUMBERS NEVER BECOME MONEY.
// The model returned item_code + qty. Every unit price below is read from the Data Table rows
// fetched earlier, so a hallucinated price cannot reach a customer - a hallucinated CODE just
// gets dropped into unmatched_note and the human sees it at the gate.
const GATE_STATE = "awaiting_human_approval"; // every draft lands here. No auto-send path exists.
const QTY_CEILING = 500; // a photo cannot justify more than this; clamp and flag.

const intake = $("Read the photo and the note").first().json;
const prompt = $("Build the vision request").first().json;

// --- rate card, keyed by code -------------------------------------------------
const card = {};
for (const row of $("Load the rate card").all()) {
  const r = row.json;
  const code = String(r.item_code ?? "").trim();
  if (!code) continue;
  card[code.toUpperCase()] = {
    item_code: code,
    item_label: String(r.item_label ?? code),
    unit_label: String(r.unit_label ?? "each"),
    unit_price: Number(r.unit_price ?? 0) || 0,
    min_qty: Number(r.min_qty ?? 0) || 0,
  };
}

// --- whatever the vision call gave us ----------------------------------------
const raw = items[0] ? items[0].json : {};
let parsed = null;
let readFailure = "";

try {
  const text =
    raw?.choices?.[0]?.message?.content ??
    raw?.content?.[0]?.text ??
    raw?.output_text ??
    "";
  const body = typeof text === "string" ? text : JSON.stringify(text);
  const start = body.indexOf("{");
  const end = body.lastIndexOf("}");
  if (start === -1 || end === -1)
    throw new Error("no JSON object in the model reply");
  parsed = JSON.parse(body.slice(start, end + 1));
} catch (err) {
  readFailure = String(err.message || err);
}

const picks = Array.isArray(parsed?.lines) ? parsed.lines : [];

// --- build the priced lines ---------------------------------------------------
const lines = [];
const unmatched = [];
let clamped = false;

for (const pick of picks.slice(0, 12)) {
  const code = String(pick?.item_code ?? "")
    .trim()
    .toUpperCase();
  const hit = card[code];
  if (!hit) {
    if (code) unmatched.push(code);
    continue;
  }
  let qty = Number(pick?.qty ?? 0);
  if (!isFinite(qty) || qty <= 0) qty = hit.min_qty || 1;
  if (qty > QTY_CEILING) {
    qty = QTY_CEILING;
    clamped = true;
  }
  if (hit.min_qty && qty < hit.min_qty) qty = hit.min_qty;
  qty = Math.round(qty * 100) / 100;

  lines.push({
    item_code: hit.item_code,
    item_label: hit.item_label,
    unit_label: hit.unit_label,
    qty,
    unit_price: hit.unit_price,
    line_total: Math.round(qty * hit.unit_price * 100) / 100,
    reason: String(pick?.reason ?? "").slice(0, 200),
  });
}

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);
const subtotal =
  Math.round(lines.reduce((a, l) => a + l.line_total, 0) * 100) / 100;
const taxRate = Number(intake.tax_rate ?? 0) || 0;
const tax = Math.round(subtotal * taxRate * 100) / 100;
const total = Math.round((subtotal + tax) * 100) / 100;

// --- why a human has to look at this -----------------------------------------
const flags = [];
if (readFailure) flags.push("vision_call_unreadable: " + readFailure);
if (intake.intake_status === "rejected_no_usable_photo")
  flags.push("no_usable_photo");
if (intake.intake_status === "accepted_photo_only")
  flags.push("no_note_from_site");
if (!lines.length) flags.push("nothing_priced");
if (unmatched.length)
  flags.push("model_invented_codes: " + unmatched.join(","));
if (clamped) flags.push("quantity_clamped_to_" + QTY_CEILING);
if (parsed?.needs_site_visit === true)
  flags.push("model_says_site_visit_needed");
if (Array.isArray(parsed?.missing_info) && parsed.missing_info.length)
  flags.push("missing_info: " + parsed.missing_info.slice(0, 4).join("; "));

const quoteText = [
  `DRAFT QUOTE ${intake.quote_ref}  (site ref ${intake.site_ref})`,
  `Prepared from one site photo on ${intake.received_at}. NOT SENT - awaiting human approval.`,
  "",
  ...(lines.length
    ? lines.map(
        (l) =>
          `${l.qty} x ${l.item_label} (${l.item_code}, ${l.unit_label}) @ ${intake.currency_code} ${money(l.unit_price)} = ${intake.currency_code} ${money(l.line_total)}`,
      )
    : ["(no line item could be priced from this photo)"]),
  "",
  `Subtotal  ${intake.currency_code} ${money(subtotal)}`,
  `Tax @${Math.round(taxRate * 100)}%  ${intake.currency_code} ${money(tax)}`,
  `TOTAL     ${intake.currency_code} ${money(total)}`,
  "",
  "Prices come from your own rate card, not from the model. Quantities are estimated from a",
  "photograph and are not measurements. Nothing above has been sent to anyone.",
].join("\n");

return [
  {
    json: {
      quote_ref: intake.quote_ref,
      received_at: intake.received_at,
      site_ref: intake.site_ref,
      requester_name: intake.requester_name,
      requester_email: intake.requester_email,
      photo_url: intake.photo_url,
      site_note: intake.site_note,
      trade_code: intake.trade_code,
      currency_code: intake.currency_code,
      card_rows: prompt.card_rows,
      observed_summary: String(parsed?.observed ?? "").slice(0, 400),
      line_items_text: JSON.stringify(lines),
      line_count: lines.length,
      subtotal_amount: subtotal,
      tax_amount: tax,
      total_amount: total,
      model_confidence: Number(parsed?.confidence ?? 0) || 0,
      unmatched_note: flags.join(" | ") || "none",
      quote_summary: quoteText,
      approval_status: GATE_STATE,
      release_mode:
        "NOT SENT - no customer-facing send node exists on this canvas",
    },
  },
];
